import "server-only";
import path from "node:path";
import { mkdir } from "node:fs/promises";

/** Project uploads live outside the web root and are served only through /api/files. */
export const FILES_DIR = path.resolve(process.env.FILES_DIR || "./files");

export async function ensureFilesDir() {
  await mkdir(FILES_DIR, { recursive: true });
  return FILES_DIR;
}

export const filePath = (storedName) => {
  // storedName is generated by us, but never let it climb out of the folder.
  const p = path.join(FILES_DIR, path.basename(storedName));
  return p;
};

export const isPreviewable = (mime) => /^(image|video|audio)\//.test(mime) || mime === "application/pdf";
